package com.oshi.messenger

import com.oshi.messenger.network.v2.devicemailbox.SentCopy
import com.oshi.messenger.service.GroupManager
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.util.Base64

/**
 * __GROUP_E2E_V2_2026_09_23__ Android's group emitters and receive rules against the golden
 * vectors of docs/GROUP_E2E_V2_SPEC.md (docs/fixtures/group_e2e_v2/vectors.json, generated by the
 * independent Python reference `gen_vectors.py`). iOS and Desktop check the same file.
 *
 * Equality is SEMANTIC (spec §9): parsed JSON, key order free, numbers as doubles.
 */
class GroupE2EV2VectorsTest {

    private val v: JSONObject by lazy {
        val f = generateSequence(File("").absoluteFile) { it.parentFile }
            .map { File(it, "docs/fixtures/group_e2e_v2/vectors.json") }
            .firstOrNull { it.isFile } ?: error("vectors.json not found above ${File("").absolutePath}")
        JSONObject(f.readText())
    }
    private val c get() = v.getJSONObject("constants")
    private fun named(section: String, name: String): JSONObject {
        val a = v.getJSONArray(section)
        for (i in 0 until a.length()) if (a.getJSONObject(i).getString("name") == name) return a.getJSONObject(i)
        error("no vector $section/$name")
    }
    private fun b64d(s: String) = String(Base64.getDecoder().decode(s), Charsets.UTF_8)
    private fun b64e(s: String) = Base64.getEncoder().encodeToString(s.toByteArray(Charsets.UTF_8))

    private fun same(a: Any?, b: Any?): Boolean = when {
        a is JSONObject && b is JSONObject ->
            a.keySet() == b.keySet() && a.keySet().all { same(a.opt(it), b.opt(it)) }
        a is JSONArray && b is JSONArray -> a.length() == b.length() && (0 until a.length()).all { same(a.opt(it), b.opt(it)) }
        a is Number && b is Number -> Math.abs(a.toDouble() - b.toDouble()) < 1e-6
        a == JSONObject.NULL || b == JSONObject.NULL -> (a == null || a == JSONObject.NULL) && (b == null || b == JSONObject.NULL)
        else -> a == b
    }
    private fun assertSame(what: String, expected: Any, actual: Any) =
        assertTrue("$what\nexpected $expected\nactual   $actual", same(expected, actual))

    private val apple get() = c.getDouble("tsAppleEpoch")
    private val gid get() = c.getString("groupId")
    private val a get() = c.getString("A")
    private val b get() = c.getString("B")
    private val cc get() = c.getString("C")
    private val d get() = c.getString("D")
    private val mid get() = c.getString("messageId")
    private val sid get() = c.getString("otherId")

    private fun contentMessage(body: String, id: String) = JSONObject(
        GroupManager.wireGroupMessageJson(id, gid, a, apple, b64e(body), null, null, body, includeBodyCompat = true)
    )

    @Test fun content_text_reply_reaction_typing_matchTheVectors() {
        for (name in listOf("text", "reply", "reaction_add", "reaction_remove", "typing")) {
            val vec = named("content", name)
            val expected = vec.getJSONObject("groupMessage")
            val actual = contentMessage(vec.getString("body"), expected.getString("id"))
            assertSame(name, expected, actual)
            // The envelope plaintext is base64(JSON) and decodes to the same message.
            assertSame("$name plaintext", expected, JSONObject(b64d(vec.getString("plaintext"))))
        }
    }

    @Test fun bodyBuilders_reply_typing_matchTheVectors() {
        val reply = GroupManager.buildReplyEnvelope("yes", mid, b, "are you in?", c.getLong("tsUnixMs"), null)
        val vReply = named("content", "reply").getString("body")
        assertEquals(vReply.substring(0, 8), reply.substring(0, 8))
        assertSame("reply body", JSONObject(vReply.removePrefix(GroupManager.REPLY_PREFIX)), JSONObject(reply.removePrefix(GroupManager.REPLY_PREFIX)))

        val typing = GroupManager.buildGroupTypingPayload(a, true, c.getLong("tsUnixMs"), gid, "Alice")
        val vTyping = named("content", "typing").getString("body")
        assertTrue(typing.startsWith(GroupManager.TYPING_PREFIX) && vTyping.startsWith(GroupManager.TYPING_PREFIX))
        assertSame("typing body", JSONObject(vTyping.removePrefix(GroupManager.TYPING_PREFIX)), JSONObject(typing.removePrefix(GroupManager.TYPING_PREFIX)))
    }

    @Test fun reaction_parse_bindsTheReactorToTheEnvelopeSender() {
        val body = named("content", "reaction_add").getString("body")
        val p = GroupManager.parseGroupReaction(body, a)
        assertNotNull(p); assertEquals(mid, p!!.messageId); assertFalse(p.isRemoval)
        // A payload claiming A but delivered by B's ratchet is B's reaction (spec §2.3).
        assertEquals(b, GroupManager.parseGroupReaction(body, b)!!.senderPublicKey)
        assertTrue(GroupManager.parseGroupReaction(named("content", "reaction_remove").getString("body"), a)!!.isRemoval)
    }

    @Test fun systemMessages_edit_delete_matchTheVectors() {
        val ts = c.getLong("tsUnixMs")
        val edit = JSONObject(GroupManager.buildGroupEditSystemMessageJson(gid, sid, mid, "hello group (edited)", a, ts))
        assertSame("edit", named("content", "edit").getJSONObject("groupMessage"), edit)
        val del = JSONObject(GroupManager.buildGroupDeleteSystemMessageJson(gid, sid, mid, a, ts))
        assertSame("delete", named("content", "delete").getJSONObject("groupMessage"), del)
    }

    @Test fun media_strippedGroupMessage_matchesTheVector() {
        val vec = named("media", "photo")
        val actual = JSONObject(GroupManager.wireGroupMessageJson(mid, gid, a, apple, "", "photo", "photo.jpg", "sunset", includeBodyCompat = false))
        assertSame("media groupMessage", vec.getJSONObject("groupMessage"), actual)
        assertSame("media key.groupMessage", vec.getJSONObject("groupMessage"),
            JSONObject(b64d(vec.getJSONObject("keyMessage").getString("groupMessage"))))
    }

    private fun definition(name: String, members: List<String>, admins: List<String>, version: Int, description: String? = "weekly sync",
                           evicted: List<String>? = null, pinned: String? = null, pinnedBy: String? = null, avatar: String? = null,
                           picture: String? = null, pictureBy: String? = null): JSONObject {
        val ms = 1_790_000_000_000L
        return JSONObject(GroupManager.buildIosMessageGroupJson(
            groupId = gid, name = name, typeRaw = "collaborative", adminPublicKey = a,
            memberKeys = members, adminKeys = admins, createdAtMs = ms, lastActivityMs = ms,
            groupPictureBase64 = picture, groupPictureUpdatedBy = pictureBy, groupPictureUpdatedAtMs = if (picture != null) ms else null,
            pinnedMessageId = pinned, pinnedBy = pinnedBy, avatar = avatar,
            stateVersion = version, description = description, evictedMemberKeys = evicted
        ))
    }

    @Test fun state_definitions_matchTheVectors() {
        val pre = c.getString("groupUpdatePrefix")
        assertEquals(GroupManager.GROUP_UPDATE_PREFIX, pre)
        fun check(n: String, actual: JSONObject) {
            val vec = named("state", n)
            assertSame(n, vec.getJSONObject("json"), actual)
            assertSame("$n plaintext", vec.getJSONObject("json"), JSONObject(vec.getString("plaintext").removePrefix(pre)))
        }
        check("create", definition("Team", listOf(a, b, cc), listOf(a), 1))
        check("rename", definition("Team 2", listOf(a, b, cc), listOf(a), 2))
        check("add_member", definition("Team 2", listOf(a, b, cc, d), listOf(a), 3))
        check("remove_member", definition("Team 2", listOf(a, b, d), listOf(a), 4, evicted = listOf(cc)))
        check("promote_admin", definition("Team 2", listOf(a, b, d), listOf(a, d), 5, evicted = listOf(cc)))
        check("pin", definition("Team 2", listOf(a, b, d), listOf(a), 6, evicted = listOf(cc), pinned = mid, pinnedBy = a))
        check("avatar_emoji", definition("Team 2", listOf(a, b, d), listOf(a), 7, evicted = listOf(cc), avatar = "🚀"))
        check("picture", definition("Team 2", listOf(a, b, d), listOf(a), 8, description = null, picture = "/9j/AA==", pictureBy = a))
        check("rename_minimal", JSONObject(GroupManager.buildGroupRenamedJson(gid, "Team 2")))
        check("remove_member_minimal", JSONObject(GroupManager.buildMemberRemovedJson(gid, cc)))
        check("leave", JSONObject(GroupManager.buildMemberRemovedJson(gid, b)))
    }

    /**
     * __GROUP_COMPAT_IGNORE_2026_09_23__ A pure rename sends, after the definition, EXACTLY the
     * spec's `rename_minimal` plaintext — no legacy `{"type":"updated"}` (Desktop logged it as
     * REJECTED_MALFORMED). `updated` survives only for a description change.
     */
    @Test fun renameCompanions_areExactlyTheSpecVector() {
        val vec = named("state", "rename_minimal")
        val frames = GroupManager.updateCompanionFrames(gid, "Team 2", "", renamed = true, descriptionChanged = false)
        assertEquals(1, frames.size)
        val pre = GroupManager.GROUP_UPDATE_PREFIX
        assertTrue(frames[0].startsWith(pre))
        assertSame("rename companion", vec.getJSONObject("json"), JSONObject(frames[0].removePrefix(pre)))
        assertTrue(frames.none { JSONObject(it.removePrefix(pre)).optString("type") == "updated" })

        val withDesc = GroupManager.updateCompanionFrames(gid, "Team 2", "weekly sync", renamed = false, descriptionChanged = true)
        assertEquals(listOf("updated"), withDesc.map { JSONObject(it.removePrefix(pre)).getString("type") })
        assertTrue(GroupManager.updateCompanionFrames(gid, "Team 2", "", renamed = false, descriptionChanged = false).isEmpty())
    }

    @Test fun receiver_rules_matchTheVectors() {
        // Every legitimate content vector is authentic from its envelope sender.
        val content = v.getJSONArray("content")
        for (i in 0 until content.length()) {
            val vec = content.getJSONObject(i)
            val env = vec.getJSONObject("envelope")
            assertTrue(vec.getString("name"),
                GroupManager.v2ContentAuthentic(vec.getJSONObject("groupMessage"), env.getString("from"), env.getString("groupId")))
        }
        for (n in listOf("sender_mismatch", "system_actor_mismatch")) {
            val vec = named("receiver", n)
            assertFalse(n, GroupManager.v2ContentAuthentic(vec.getJSONObject("groupMessage"), vec.getString("envelopeFrom"), gid))
        }
        // A GroupMessage claiming another group than its envelope is dropped (spec §3 step 3).
        assertFalse(GroupManager.v2ContentAuthentic(named("content", "text").getJSONObject("groupMessage"), a,
            "11111111-2222-3333-4444-555555555555"))
        // Lowercase Android spelling of the same group id is the same group.
        assertTrue(GroupManager.v2ContentAuthentic(named("content", "text").getJSONObject("groupMessage"), a, gid.lowercase()))
        for (n in listOf("stale_definition", "equal_definition", "unversioned_definition")) {
            val vec = named("receiver", n)
            val local = if (vec.isNull("local")) null else vec.getInt("local")
            assertEquals(n, vec.getBoolean("apply"), GroupManager.stateVersionAccepts(local, vec.getInt("incoming")))
        }
    }

    @Test fun groupSentCopy_roundTrips() {
        val vec = named("sentCopy", "group_text_self_copy").getJSONObject("plaintext")
        val enc = SentCopy(null, gid, vec.getString("message"), mid, c.getString("iso")).encode()
        assertSame("sent-copy", vec, JSONObject(String(enc, Charsets.UTF_8)))
        val parsed = SentCopy.parse(enc)!!
        assertEquals(gid, parsed.groupId); assertEquals(mid, parsed.msgId)
        assertEquals(named("content", "text").getString("plaintext"), parsed.message)
    }
}
